Describe 'run status and detail (status / show / history)' {
    BeforeAll {
        # write raw events with fixed timestamps so elapsed times are deterministic
        $script:addEv = {
            param($path, [string]$ts, [string]$type, [hashtable]$props)
            $o = [ordered]@{ ts = $ts; type = $type }
            foreach ($k in $props.Keys) { $o[$k] = $props[$k] }
            Add-Content -LiteralPath $path -Value ($o | ConvertTo-Json -Compress -Depth 5)
        }
        $script:t0 = [datetime]::new(2026, 11, 17, 15, 0, 0, [System.DateTimeKind]::Utc).ToLocalTime()
        $script:iso = { param([int]$sec) $t0.AddSeconds($sec).ToString('yyyy-MM-ddTHH:mm:sszzz') }
    }
    BeforeEach {
        $script:n = [guid]::NewGuid().ToString('n').Substring(0, 8)
        $script:ev = Join-Path $Work "st-$n.jsonl"
        $script:lock = Join-Path $Work "st-$n.lock"
    }

    It 'formats durations compactly and culture-independently' {
        Format-Duration 7.5 | Should -Be '7.5s'
        Format-Duration 42 | Should -Be '42s'
        Format-Duration 302 | Should -Be '5m02s'
        Format-Duration 3780 | Should -Be '1h03m'
    }

    It 'tells finished, running and interrupted runs apart' {
        & $addEv $ev (& $iso 0) 'run.start' @{ runId = 'r-0001' }
        & $addEv $ev (& $iso 5) 'run.end' @{ runId = 'r-0001'; summary = @{ ok = 1; failed = 0; planned = 1 } }
        & $addEv $ev (& $iso 10) 'run.start' @{ runId = 'r-0002' }
        & $addEv $ev (& $iso 20) 'run.start' @{ runId = 'r-0003' }
        $events = @(Get-BackupEvents -EventsPath $ev)

        Set-Content -LiteralPath $lock -Value $PID   # a live process holds the lock
        $states = @(Get-RunStates -Events $events -LockPath $lock)
        ($states | ForEach-Object { $_.State }) -join ',' | Should -Be 'finished,interrupted,running'
        $states[2].Pid | Should -Be $PID

        Remove-Item -LiteralPath $lock               # nobody holds it: the newest run died too
        ((Get-RunStates -Events $events -LockPath $lock) | ForEach-Object { $_.State }) -join ',' | Should -Be 'finished,interrupted,interrupted'
    }

    It 'resolves a run by latest, full id or unique ending' {
        $runs = @(
            [pscustomobject]@{ RunId = '20261117-152140-332d' },
            [pscustomobject]@{ RunId = '20261117-160000-a32d' },
            [pscustomobject]@{ RunId = '20261117-170000-beef' })
        (Resolve-RunRef -Runs $runs -Ref 'latest').RunId | Should -Be '20261117-170000-beef'
        (Resolve-RunRef -Runs $runs -Ref '').RunId | Should -Be '20261117-170000-beef'
        (Resolve-RunRef -Runs $runs -Ref '20261117-152140-332d').RunId | Should -Be '20261117-152140-332d'
        (Resolve-RunRef -Runs $runs -Ref '332d').RunId | Should -Be '20261117-152140-332d'
        { Resolve-RunRef -Runs $runs -Ref '32d' } | Should -Throw '*matches several runs*'
        { Resolve-RunRef -Runs $runs -Ref 'zzzz' } | Should -Throw "*no run matches*"
    }

    It 'shows the step in progress, finished services and pending ones for a running run' {
        & $addEv $ev (& $iso 0) 'run.start' @{ runId = 'r1' }
        & $addEv $ev (& $iso 0) 'run.plan' @{ runId = 'r1'; plan = @('a', 'b', 'c') }
        & $addEv $ev (& $iso 1) 'step.start' @{ runId = 'r1'; svc = 'a'; step = 'dump' }
        & $addEv $ev (& $iso 4) 'step.end' @{ runId = 'r1'; svc = 'a'; step = 'dump'; status = 'ok'; durationSec = 3.1 }
        & $addEv $ev (& $iso 5) 'service.archived' @{ runId = 'r1'; svc = 'a'; snapshot = 'deadbeefcafe0123' }
        & $addEv $ev (& $iso 5) 'service.end' @{ runId = 'r1'; svc = 'a'; status = 'ok'; bytes = 7.2MB }
        & $addEv $ev (& $iso 6) 'step.start' @{ runId = 'r1'; svc = 'b'; step = 'stop' }
        & $addEv $ev (& $iso 55) 'step.end' @{ runId = 'r1'; svc = 'b'; step = 'stop'; status = 'ok'; durationSec = 49 }
        & $addEv $ev (& $iso 60) 'step.start' @{ runId = 'r1'; svc = 'b'; step = 'hot-dump' }
        Set-Content -LiteralPath $lock -Value $PID
        $events = @(Get-BackupEvents -EventsPath $ev)
        $run = (Get-RunStates -Events $events -LockPath $lock)[-1]
        $detail = Get-RunDetail -Events $events -Run $run
        $text = (Format-RunDetail -Detail $detail -Now $t0.AddSeconds(300)) -join "`n"

        $text | Should -Match 'RUNNING  run r1 .*\(5m00s\)'
        $text | Should -Match 'a\s+ok\s+7\.2 MB\s+snap deadbeef\s+dump 3\.1s'
        $text | Should -Match 'b\s+> hot-dump \(4m00s\).*stop 49s'
        $text | Should -Match 'c\s+pending'
        (Format-RunHistoryLine -Detail $detail -Now $t0.AddSeconds(300)) | Should -Match 'r1  RUNNING \(5m00s\)  \[a:ok b:hot-dump\.\.\.\]'
    }

    It 'flags the step a dead run stopped in, and services it never reached' {
        & $addEv $ev (& $iso 0) 'run.start' @{ runId = 'r1' }
        & $addEv $ev (& $iso 0) 'run.plan' @{ runId = 'r1'; plan = @('a', 'b') }
        & $addEv $ev (& $iso 1) 'step.start' @{ runId = 'r1'; svc = 'a'; step = 'dump' }
        $events = @(Get-BackupEvents -EventsPath $ev)
        $run = (Get-RunStates -Events $events -LockPath $lock)[-1]
        $detail = Get-RunDetail -Events $events -Run $run
        $text = (Format-RunDetail -Detail $detail) -join "`n"

        $text | Should -Match 'INTERRUPTED  run r1'
        $text | Should -Match 'a\s+! died in dump'
        $text | Should -Match 'may have left it down'
        $text | Should -Match 'b\s+not reached'
        (Format-RunHistoryLine -Detail $detail) | Should -Match 'r1  INTERRUPTED  \[a:dump\.\.\.\]'
    }

    It 'shows skipped and invalid services of a finished run, with problems and archive failures' {
        & $addEv $ev (& $iso 0) 'run.start' @{ runId = 'r1' }
        & $addEv $ev (& $iso 0) 'service.skip' @{ runId = 'r1'; svc = 'a'; reason = 'covered' }
        & $addEv $ev (& $iso 1) 'service.end' @{ runId = 'r1'; svc = 'b'; status = 'fail'; reason = 'invalid'; problems = @('hot dir missing: /x'); bytes = 0 }
        & $addEv $ev (& $iso 2) 'step.start' @{ runId = 'r1'; svc = 'c'; step = 'sync-archive' }
        & $addEv $ev (& $iso 3) 'step.end' @{ runId = 'r1'; svc = 'c'; step = 'sync-archive'; status = 'fail'; durationSec = 1 }
        & $addEv $ev (& $iso 3) 'service.syncfail' @{ runId = 'r1'; svc = 'c'; reason = 'repo locked' }
        & $addEv $ev (& $iso 3) 'service.end' @{ runId = 'r1'; svc = 'c'; status = 'fail'; bytes = 0; error = 'sync-archive failed; nothing retained' }
        & $addEv $ev (& $iso 65) 'run.end' @{ runId = 'r1'; summary = @{ ok = 0; failed = 2; planned = 3 } }
        $events = @(Get-BackupEvents -EventsPath $ev)
        $detail = Get-RunDetail -Events $events -Run (Get-RunStates -Events $events -LockPath $lock)[-1]
        $text = (Format-RunDetail -Detail $detail) -join "`n"

        $text | Should -Match 'run r1 .* \(1m05s\)  ok=0 failed=2 planned=3'
        $text | Should -Match 'a\s+skipped \(covered\)'
        $text | Should -Match 'b\s+INVALID'
        $text | Should -Match '- hot dir missing: /x'
        $text | Should -Match 'c\s+FAIL.*sync-archive FAIL 1s'
        $text | Should -Match '! archive failed: repo locked'
        (Format-RunHistoryLine -Detail $detail) | Should -Match 'r1  ok=0 failed=2 planned=3  \[a:covered b:fail c:fail\]'
    }
}

Describe 'spool lifecycle (wip -> stage -> ready)' {
    BeforeEach {
        $script:n = [guid]::NewGuid().ToString('n').Substring(0, 8)
        $script:ev = Join-Path $Work "lc-$n.jsonl"
        $script:root = Join-Path $Work "lc-$n"
        $script:paths = @{ BaseDir = $script:TestsDir; EventsPath = $script:ev; LockPath = ($script:root + '.lock'); SpoolRoot = $script:root }
    }

    It 'publishes a successful backup to ready/ and clears wip/stage' {
        $cfg = @'
{ "window": { "open": "00:00", "close": "23:59" },
  "services": { "app": { "enabled": true, "mandatory": true, "script": "fixtures/mock-service.ps1",
    "steps": [ { "name": "dump", "resources": [] },
               { "name": "start", "resources": [], "alwaysRun": true } ] } } }
'@ | ConvertFrom-Json
        $runId = Invoke-BackupRun -Config $cfg -Paths $paths -ForceWindow -WarningAction SilentlyContinue
        $runId | Should -Not -BeNullOrEmpty
        (Test-Path (Join-Path $root 'ready/app/data.bin')) | Should -BeTrue
        (Test-Path (Join-Path $root 'ready/app/config.bin')) | Should -BeTrue
        (Test-Path (Join-Path $root 'wip/app')) | Should -BeFalse
        (Test-Path (Join-Path $root 'stage/app')) | Should -BeFalse
        $se = Get-BackupEvents -EventsPath $ev | Where-Object { $_.type -eq 'service.end' -and $_.svc -eq 'app' } | Select-Object -First 1
        $se.status | Should -Be 'ok'
        $se.bytes | Should -BeGreaterThan 0
    }

    It 'does not publish a failed backup, but still runs recovery' {
        $cfg = @'
{ "window": { "open": "00:00", "close": "23:59" },
  "services": { "app": { "enabled": true, "mandatory": true, "script": "fixtures/mock-service.ps1",
    "steps": [ { "name": "dump", "resources": [] },
               { "name": "boom", "resources": [] },
               { "name": "start", "resources": [], "alwaysRun": true } ] } } }
'@ | ConvertFrom-Json
        Invoke-BackupRun -Config $cfg -Paths $paths -ForceWindow -WarningAction SilentlyContinue | Out-Null
        (Test-Path (Join-Path $root 'ready/app')) | Should -BeFalse
        $events = Get-BackupEvents -EventsPath $ev
        ($events | Where-Object { $_.type -eq 'service.end' -and $_.svc -eq 'app' } | Select-Object -First 1).status | Should -Be 'fail'
        @($events | Where-Object { $_.type -eq 'step.start' -and $_.step -eq 'start' }).Count | Should -BeGreaterThan 0
    }

    It 'replaces an unconsumed previous backup and notifies' {
        New-Item -ItemType Directory -Force -Path (Join-Path $root 'ready/app') | Out-Null
        Set-Content -LiteralPath (Join-Path $root 'ready/app/old.bin') -Value 'old'
        $cfg = @'
{ "window": { "open": "00:00", "close": "23:59" },
  "services": { "app": { "enabled": true, "mandatory": true, "script": "fixtures/mock-service.ps1",
    "steps": [ { "name": "dump", "resources": [] },
               { "name": "start", "resources": [], "alwaysRun": true } ] } } }
'@ | ConvertFrom-Json
        Invoke-BackupRun -Config $cfg -Paths $paths -ForceWindow -WarningAction SilentlyContinue | Out-Null
        @(Get-BackupEvents -EventsPath $ev | Where-Object { $_.type -eq 'service.replaced' }).Count | Should -BeGreaterThan 0
        (Test-Path (Join-Path $root 'ready/app/data.bin')) | Should -BeTrue
        (Test-Path (Join-Path $root 'ready/app/old.bin')) | Should -BeFalse
    }

    It 'reaps trash/ at run start' {
        New-Item -ItemType Directory -Force -Path (Join-Path $root 'trash/junk') | Out-Null
        Set-Content -LiteralPath (Join-Path $root 'trash/junk/f') -Value 'x'
        $cfg = @'
{ "window": { "open": "00:00", "close": "23:59" },
  "services": { "app": { "enabled": true, "mandatory": true, "script": "fixtures/mock-service.ps1",
    "steps": [ { "name": "dump", "resources": [] },
               { "name": "start", "resources": [], "alwaysRun": true } ] } } }
'@ | ConvertFrom-Json
        Invoke-BackupRun -Config $cfg -Paths $paths -ForceWindow -WarningAction SilentlyContinue | Out-Null
        (Test-Path (Join-Path $root 'trash/junk')) | Should -BeFalse
    }

    It 'sync-only (publishToReady=false) archives then leaves nothing in ready/' {
        $cfg = @'
{ "window": { "open": "00:00", "close": "23:59" },
  "services": { "app": { "enabled": true, "mandatory": true, "script": "fixtures/mock-service.ps1",
    "publishToReady": false,
    "syncArchive": { "script": "fixtures/mock-service.ps1", "env": {} },
    "steps": [ { "name": "dump", "resources": [] },
               { "name": "start", "resources": [], "alwaysRun": true } ] } } }
'@ | ConvertFrom-Json
        Invoke-BackupRun -Config $cfg -Paths $paths -ForceWindow -WarningAction SilentlyContinue | Out-Null
        (Test-Path (Join-Path $root 'ready/app')) | Should -BeFalse
        @(Get-BackupEvents -EventsPath $ev | Where-Object { $_.type -eq 'step.end' -and $_.step -eq 'sync-archive' -and $_.status -eq 'ok' }).Count | Should -BeGreaterThan 0
    }

    It 'sync-only (publishToReady=false): a sync failure retains nothing and fails the service' {
        $cfg = @'
{ "window": { "open": "00:00", "close": "23:59" },
  "services": { "app": { "enabled": true, "mandatory": true, "script": "fixtures/mock-service.ps1",
    "publishToReady": false,
    "syncArchive": { "script": "fixtures/mock-service.ps1", "env": { "MOCK_ARCHIVE_FAIL": "1" } },
    "steps": [ { "name": "dump", "resources": [] },
               { "name": "start", "resources": [], "alwaysRun": true } ] } } }
'@ | ConvertFrom-Json
        Invoke-BackupRun -Config $cfg -Paths $paths -ForceWindow -WarningAction SilentlyContinue | Out-Null
        @(Get-BackupEvents -EventsPath $ev | Where-Object { $_.type -eq 'service.syncfail' }).Count | Should -BeGreaterThan 0
        # config honored: not force-published to a ready/ nobody consumes
        (Test-Path (Join-Path $root 'ready/app')) | Should -BeFalse
        # and nothing was archived -> the service is a failure, not a silent ok
        $endE = @(Get-BackupEvents -EventsPath $ev | Where-Object { $_.type -eq 'service.end' -and $_.svc -eq 'app' })
        $endE[-1].status | Should -Be 'fail'
    }

    It 'publishToReady=true: a sync failure still publishes to ready/ and stays ok (archiver has it)' {
        $cfg = @'
{ "window": { "open": "00:00", "close": "23:59" },
  "services": { "app": { "enabled": true, "mandatory": true, "script": "fixtures/mock-service.ps1",
    "publishToReady": true,
    "syncArchive": { "script": "fixtures/mock-service.ps1", "env": { "MOCK_ARCHIVE_FAIL": "1" } },
    "steps": [ { "name": "dump", "resources": [] },
               { "name": "start", "resources": [], "alwaysRun": true } ] } } }
'@ | ConvertFrom-Json
        $runId = Invoke-BackupRun -Config $cfg -Paths $paths -ForceWindow -WarningAction SilentlyContinue
        @(Get-BackupEvents -EventsPath $ev | Where-Object { $_.type -eq 'service.syncfail' }).Count | Should -BeGreaterThan 0
        (Test-Path (Join-Path $root 'ready/app/data.bin')) | Should -BeTrue
        $endE = @(Get-BackupEvents -EventsPath $ev | Where-Object { $_.type -eq 'service.end' -and $_.svc -eq 'app' })
        $endE[-1].status | Should -Be 'ok'
        # the dead-man's-switch report must still surface the archive failure
        (Format-RunReport -EventsPath $ev -RunId $runId) | Should -Match 'archive failed'
    }

    It 'archive-restic: snapshots via restic and logs the snapshot id (publishToReady=false)' -Skip:($IsWindows) {
        $repoDir = Join-Path $Work "resticrepo-$n"
        $cfg = (@'
{ "window": { "open": "00:00", "close": "23:59" },
  "services": { "app": { "enabled": true, "mandatory": true, "script": "fixtures/mock-service.ps1",
    "publishToReady": false,
    "syncArchive": { "script": "../src/recipes/archive-restic.ps1",
      "env": { "RESTIC_REPOSITORY": "__REPO__", "RESTIC_BIN": "__STUB__", "RESTIC_PASSWORD": "test" } },
    "steps": [ { "name": "dump", "resources": [] },
               { "name": "start", "resources": [], "alwaysRun": true } ] } } }
'@ -replace '__REPO__', ($repoDir -replace '\\', '/') -replace '__STUB__', ($script:resticStub -replace '\\', '/')) | ConvertFrom-Json
        Invoke-BackupRun -Config $cfg -Paths $paths -ForceWindow -WarningAction SilentlyContinue | Out-Null
        $arch = @(Get-BackupEvents -EventsPath $ev | Where-Object { $_.type -eq 'service.archived' -and $_.svc -eq 'app' })
        $arch.Count | Should -BeGreaterThan 0
        $arch[-1].snapshot | Should -Be 'deadbeefcafe'
        # the restic repo is the archive -> no local copy kept in ready/
        (Test-Path (Join-Path $root 'ready/app')) | Should -BeFalse
        (@(Get-BackupEvents -EventsPath $ev | Where-Object { $_.type -eq 'service.end' -and $_.svc -eq 'app' }))[-1].status | Should -Be 'ok'
    }

    It 'archive-restic: backs up "." from inside the stage dir, with relative local paths pinned' -Skip:($IsWindows) {
        $repoDir = Join-Path $Work "resticrepoR-$n"
        $pwFile = Join-Path $Work "pwR-$n"
        Set-Content -LiteralPath $pwFile -Value 'secret'
        $log = Join-Path $Work "stublog-$n"
        $here = (Get-Location).Path
        $cfg = (@'
{ "window": { "open": "00:00", "close": "23:59" },
  "services": { "app": { "enabled": true, "mandatory": true, "script": "fixtures/mock-service.ps1",
    "publishToReady": false,
    "syncArchive": { "script": "../src/recipes/archive-restic.ps1",
      "env": { "RESTIC_REPOSITORY": "__REPO__", "RESTIC_BIN": "__STUB__", "RESTIC_PASSWORD_FILE": "__PW__", "RESTIC_STUB_LOG": "__LOG__" } },
    "steps": [ { "name": "dump", "resources": [] } ] } } }
'@ -replace '__REPO__', ([System.IO.Path]::GetRelativePath($here, $repoDir) -replace '\\', '/') `
            -replace '__PW__', ([System.IO.Path]::GetRelativePath($here, $pwFile) -replace '\\', '/') `
            -replace '__STUB__', ($script:resticStub -replace '\\', '/') -replace '__LOG__', ($log -replace '\\', '/')) | ConvertFrom-Json
        Invoke-BackupRun -Config $cfg -Paths $paths -ForceWindow -WarningAction SilentlyContinue | Out-Null

        $lines = @(Get-Content -LiteralPath $log)
        $lines[0] | Should -BeLike '*stage/app'          # cwd = the service's stage dir
        $lines[1] | Should -Be 'backup'
        $lines[2] | Should -Be '.'                       # stored flat, not under the spool path
        $lines[[array]::IndexOf($lines, '-r') + 1] | Should -Be ([System.IO.Path]::GetFullPath($repoDir))
        $lines[[array]::IndexOf($lines, '--password-file') + 1] | Should -Be ([System.IO.Path]::GetFullPath($pwFile))
        (Get-Location).Path | Should -Be $here           # cwd restored after the archive step
    }

    It 'archive-restic: a restic failure retains nothing and fails the service (publishToReady=false)' -Skip:($IsWindows) {
        $repoDir = Join-Path $Work "resticrepoF-$n"
        $cfg = (@'
{ "window": { "open": "00:00", "close": "23:59" },
  "services": { "app": { "enabled": true, "mandatory": true, "script": "fixtures/mock-service.ps1",
    "publishToReady": false,
    "syncArchive": { "script": "../src/recipes/archive-restic.ps1",
      "env": { "RESTIC_REPOSITORY": "__REPO__", "RESTIC_BIN": "__STUB__", "RESTIC_PASSWORD": "test", "RESTIC_STUB_FAIL": "1" } },
    "steps": [ { "name": "dump", "resources": [] },
               { "name": "start", "resources": [], "alwaysRun": true } ] } } }
'@ -replace '__REPO__', ($repoDir -replace '\\', '/') -replace '__STUB__', ($script:resticStub -replace '\\', '/')) | ConvertFrom-Json
        Invoke-BackupRun -Config $cfg -Paths $paths -ForceWindow -WarningAction SilentlyContinue | Out-Null
        @(Get-BackupEvents -EventsPath $ev | Where-Object { $_.type -eq 'service.syncfail' -and $_.svc -eq 'app' }).Count | Should -BeGreaterThan 0
        @(Get-BackupEvents -EventsPath $ev | Where-Object { $_.type -eq 'service.archived' -and $_.svc -eq 'app' }).Count | Should -Be 0
        (Test-Path (Join-Path $root 'ready/app')) | Should -BeFalse
        (@(Get-BackupEvents -EventsPath $ev | Where-Object { $_.type -eq 'service.end' -and $_.svc -eq 'app' }))[-1].status | Should -Be 'fail'
    }

    It 'archive-copy copies the set to dest (ARCHIVE_DEST from top-level) and logs service.archived' {
        $dest = Join-Path $Work "cloud-$n"
        $cfg = (@'
{ "window": { "open": "00:00", "close": "23:59" },
  "env": { "ARCHIVE_DEST": "__DEST__" },
  "services": { "app": { "enabled": true, "mandatory": true, "script": "fixtures/mock-service.ps1",
    "publishToReady": true,
    "syncArchive": { "script": "../src/recipes/archive-copy.ps1", "env": { "ARCHIVE_KEEP": "3" } },
    "steps": [ { "name": "dump", "resources": [] }, { "name": "start", "resources": [], "alwaysRun": true } ] } } }
'@ -replace '__DEST__', ($dest -replace '\\', '/')) | ConvertFrom-Json
        Invoke-BackupRun -Config $cfg -Paths $paths -ForceWindow -WarningAction SilentlyContinue | Out-Null
        $copies = @(Get-ChildItem -Path (Join-Path $dest 'app') -Directory -ErrorAction SilentlyContinue)
        $copies.Count | Should -Be 1
        (Test-Path (Join-Path $copies[0].FullName 'data.bin')) | Should -BeTrue
        @(Get-BackupEvents -EventsPath $ev | Where-Object { $_.type -eq 'service.archived' -and $_.svc -eq 'app' }).Count | Should -BeGreaterThan 0
    }

    It 'service-level env feeds the archiver (unified env scope chain)' {
        $dest = Join-Path $Work "svcenv-$n"
        # ARCHIVE_DEST/ARCHIVE_KEEP live only in the service's own env, not in a
        # top-level block nor in syncArchive.env -> the archiver must still see them
        $cfg = (@'
{ "window": { "open": "00:00", "close": "23:59" },
  "services": { "app": { "enabled": true, "mandatory": true, "script": "fixtures/mock-service.ps1",
    "env": { "ARCHIVE_DEST": "__DEST__", "ARCHIVE_KEEP": "3" },
    "publishToReady": true,
    "syncArchive": { "script": "../src/recipes/archive-copy.ps1" },
    "steps": [ { "name": "dump", "resources": [] }, { "name": "start", "resources": [], "alwaysRun": true } ] } } }
'@ -replace '__DEST__', ($dest -replace '\\', '/')) | ConvertFrom-Json
        Invoke-BackupRun -Config $cfg -Paths $paths -ForceWindow -WarningAction SilentlyContinue | Out-Null
        (Test-Path (Join-Path $dest 'app')) | Should -BeTrue
        @(Get-BackupEvents -EventsPath $ev | Where-Object { $_.type -eq 'service.archived' -and $_.svc -eq 'app' }).Count | Should -BeGreaterThan 0
    }

    It 'isolates a broken service: it fails but other services still run' {
        $cfg = @'
{ "window": { "open": "00:00", "close": "23:59" },
  "services": {
    "broken": { "enabled": true, "mandatory": true, "script": "fixtures/throwing-recipe.ps1",
      "steps": [ { "name": "dump", "resources": [] } ] },
    "good": { "enabled": true, "mandatory": false, "script": "fixtures/mock-service.ps1",
      "steps": [ { "name": "dump", "resources": [] }, { "name": "start", "resources": [], "alwaysRun": true } ] }
  } }
'@ | ConvertFrom-Json
        Invoke-BackupRun -Config $cfg -Paths $paths -ForceWindow -WarningAction SilentlyContinue | Out-Null
        $events = Get-BackupEvents -EventsPath $ev
        ($events | Where-Object { $_.type -eq 'service.end' -and $_.svc -eq 'broken' } | Select-Object -First 1).status | Should -Be 'fail'
        ($events | Where-Object { $_.type -eq 'service.end' -and $_.svc -eq 'good' } | Select-Object -First 1).status | Should -Be 'ok'
        @($events | Where-Object { $_.type -eq 'run.end' }).Count | Should -Be 1
    }

    It 'recipe registration output does not taint the returned run id' {
        $cfg = @'
{ "window": { "open": "00:00", "close": "23:59" },
  "services": { "app": { "enabled": true, "mandatory": true, "script": "fixtures/noisy-recipe.ps1",
    "steps": [ { "name": "dump", "resources": [] } ] } } }
'@ | ConvertFrom-Json
        $runId = Invoke-BackupRun -Config $cfg -Paths $paths -ForceWindow -WarningAction SilentlyContinue
        $runId | Should -BeOfType [string]
        $runId | Should -Match '^\d{8}-\d{6}-'
    }

    It 'archive-copy prunes by the log (keep N), deleting recorded paths, leaving foreign dirs alone' {
        $dest = Join-Path $Work "cloudp-$n"
        $svcDir = Join-Path $dest 'app'
        New-Item -ItemType Directory -Force -Path $svcDir | Out-Null
        # a foreign dir the archiver never recorded -> must never be pruned
        New-Item -ItemType Directory -Force -Path (Join-Path $svcDir 'daily') | Out-Null
        # seed three prior archives in the log (oldest first) with matching dirs
        foreach ($d in '2026-11-01', '2026-11-02', '2026-11-03') {
            $p = Join-Path $svcDir ([datetime]"${d}T00:00:00").ToString('yyyyMMdd-HHmmss')
            New-Item -ItemType Directory -Force -Path $p | Out-Null
            Add-Content -LiteralPath $ev -Value (@{ ts = "${d}T00:00:00+00:00"; type = 'service.archived'; svc = 'app'; path = $p } | ConvertTo-Json -Compress)
        }
        $cfg = (@'
{ "window": { "open": "00:00", "close": "23:59" },
  "services": { "app": { "enabled": true, "mandatory": true, "script": "fixtures/mock-service.ps1",
    "publishToReady": false,
    "syncArchive": { "script": "../src/recipes/archive-copy.ps1", "env": { "ARCHIVE_DEST": "__DEST__", "ARCHIVE_KEEP": "2" } },
    "steps": [ { "name": "dump", "resources": [] } ] } } }
'@ -replace '__DEST__', ($dest -replace '\\', '/')) | ConvertFrom-Json
        Invoke-BackupRun -Config $cfg -Paths $paths -ForceWindow -WarningAction SilentlyContinue | Out-Null
        # oldest two recorded archives pruned (by their logged paths); newest kept
        (Test-Path (Join-Path $svcDir '20261101-000000')) | Should -BeFalse
        (Test-Path (Join-Path $svcDir '20261102-000000')) | Should -BeFalse
        (Test-Path (Join-Path $svcDir '20261103-000000')) | Should -BeTrue
        # the foreign dir, never in the log, is untouched
        (Test-Path (Join-Path $svcDir 'daily')) | Should -BeTrue
        # two archive-pruned events recorded
        @(Get-BackupEvents -EventsPath $ev | Where-Object { $_.type -eq 'service.archive-pruned' -and $_.svc -eq 'app' }).Count | Should -Be 2
    }

    It 'archive-gfsy routes the first archive to the yearly tier' {
        $dest = Join-Path $Work "gfsy-a-$n"
        $cfg = (@'
{ "window": { "open": "00:00", "close": "23:59" },
  "services": { "app": { "enabled": true, "mandatory": true, "script": "fixtures/mock-service.ps1",
    "publishToReady": false,
    "syncArchive": { "script": "../src/recipes/archive-gfsy.ps1", "env": { "ARCHIVE_DEST": "__DEST__" } },
