             "DCC_HOT_DIRS": "__HOT1__;__HOT2__;__HOT3__", "DCC_COMPOSE_CMD": "tar" },
    "steps": [ { "name": "dump", "resources": [] }, { "name": "hot-dump", "resources": [] } ] } } }
